WebLink.url:
{!REQUIRESCRIPT("/soap/ajax/24.0/connection.js")} 
try{ 
if('Approval Required – Legal' == '{!Contract__c.Status__c}'){
        alert('Legal Approval Required'); 
}else{
var conf = confirm('Please ensure that you’ve synced or uploaded the customer approval email with this contract'); 
if(conf == true){ 
    var contract = new sforce.SObject("Contract__c");
    contract.id = '{!Contract__c.Id}';
    contract.status__c = 'Signed by Customer';
    var result = sforce.connection.update([contract]);
    window.location.reload();
}
}
}catch(e){ 
alert('An Error has Occured. Error:' +e); 
}
